WITH kept_keys AS (SELECT page, event_type FROM web_events INTERSECT ALL SELECT page, event_type FROM web_events WHERE duration_sec <> 365), kept_rows AS (SELECT s.* FROM web_events s INNER JOIN kept_keys k ON s.page = k.page AND s.event_type = k.event_type) SELECT id, event_type, page, event_time, duration_sec, CASE WHEN event_type RLIKE '^(search|purchase)$' THEN 'GROUP_A' WHEN event_type RLIKE '^(page_view|click)$' THEN 'OTHER_ZONE' ELSE 'GROUP_B' END AS event_type_zone FROM kept_rows;
